def solve(g):
    H,W=len(g),len(g[0])
    bar=None
    for i in range(H):
        if len(set(g[i]))==1 and g[i][0]!=0: bar=g[i][0]; break
    seen=[[False]*W for _ in range(H)]
    comps={}
    for i in range(H):
        for j in range(W):
            c=g[i][j]
            if c==0 or c==bar or seen[i][j]: continue
            st=[(i,j)]; cells=[]
            while st:
                y,x=st.pop()
                if seen[y][x]: continue
                seen[y][x]=True; cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and g[ny][nx]==c and not seen[ny][nx]: st.append((ny,nx))
            comps.setdefault(c,[]).append(cells)
    tot={c:sum(len(cl) for cl in v) for c,v in comps.items()}
    obj_colors=[c for c in tot if tot[c]>8]
    mc=[c for c in tot if c!=bar and tot[c]<=8]
    out=[[0]*W for _ in range(H)]
    cur_r=min(min(y for _,_ in o) for o in [max(comps[c],key=lambda cl:min(y for y,_ in cl)) for c in obj_colors])
    placed=[]
    for c in obj_colors:
        best=max(comps[c],key=lambda cl:min(y for y,_ in cl))
        top=min(y for y,_ in best); sh=cur_r-top
        new=[(y+sh,x) for y,x in best]
        for y,x in new: out[y][x]=c
        placed.append(new)
    return out
